for (i = 0; i < 12; i++) {
  Z[i] = []; D[i] = [];
  for (j = 0; j < 12; j++) {
    Z[i][j] = rnd() * 0.8 + (i === j ? 0.2 : 0);
    D[i][j] = Math.sqrt((gx[i] - gx[j]) * (gx[i] - gx[j]) + (gy[i] - gy[j]) * (gy[i] - gy[j]));
